const n={ocnal:{baipishu:"White Paper",home1:"Unlock the World of Digital Currencies",home2:"Deposit Now",home3:"Name",home4:"Price",home5:"24h Change",home6:"Trade",home7:"Getting Started",home8:"Create an account",home9:"Register an account to enjoy more privileges and services",home10:"Register",home11:"Deposit Funds",home12:"Top up your account and start investing in cryptocurrency",home13:"Deposit crypto",home14:"Start trading",home15:"Sell, buy or copy trades, discover more",home16:"Explore the market",home17:"The cryptocurrency market is booming, encompassing digital currencies, blockchain technology, and more. The prospects are promising, but investment requires caution.",home18:"Spot",home19:"Real-time trading in the spot market with rapid price changes.",home20:"Perpetual contract",home21:"Contract trading provides leveraged trading, which can achieve high returns.",home22:"Options",home23:"Options trading provides flexible hedging strategies to control risks and obtain returns.",home24:"AI Investment",home25:"Plan with Confidence. Invest Smart. Worry Less",home26:"The Highest Annualized Return In History",home27:"Current",home28:"Regular",home29:"Buy Now",home30:"Everyone can use digital currency",home31:"From the initial experience of digital currency trading to the first purchase of financial products, the platform will help you easily earn coins",home32:"Learn about cryptocurrency",home33:"Learn all about cryptocurrency to start investing",home34:"Frequently Asked Questions",home35:"Ready to start your crypto journey?",home36:"What is a cryptocurrency exchange?",home37:"Cryptocurrency exchanges are digital marketplaces that enable users to buy and sell cryptocurrencies like Bitcoin, Ethereum, and Tether. The Binance exchange is the largest crypto exchange by trade volume. ",home38:"What products does the platform offer?",home39:"As the leading global cryptocurrency trading platform, the platform currently serves over 150 million registered users across more than 180 countries/regions. With low transaction fees, the platform offers over 350 tradable cryptocurrencies, making it the preferred choice for trading Bitcoin, altcoins, and other digital assets. <br><br> On the platform, users can: <br><br>1.Trade hundreds of digital currencies and trading pairs.<br><br>2.Buy and sell cryptocurrencies through the platform's spot trading.<br><br>3.Earn cryptocurrency interest through the platform's wealth management",home40:"How to trade cryptocurrencies on the platform",home41:"On the platform, you can trade hundreds of cryptocurrencies in the spot, futures, and options markets. To start trading, users need to register an account on the platform, complete identity verification, and deposit/purchase cryptocurrencies, then they can begin trading. ",home42:"Is this platform a secure cryptocurrency exchange?",home43:"This platform is committed to providing a secure and trustworthy trading platform. We have one of the most advanced security technologies and maintenance teams in the world, including a dedicated security team that is constantly working to ensure the security of your assets and accounts. We have also undergone independent proof of reserves verification to confirm that all user assets are supported at a 1:1 ratio. ",home44:"How to solve forgotten login password?",home45:"You can click 'Forgot Password' on the login page, and then reset the 'Login Password'. ",home46:"Why do you need Identity Authentication?",home47:"For the safety of your funds and the occurrence of money laundering activities, we need to ensure that your receiving account is associated with the current account identity information. ",home48:"Markets",home49:"The global cryptocurrency trading market supports multi-currency transactions, offering both safety and efficiency.",home50:"My Account",home51:"Deposit",home52:"Withdraw",home53:"Convert",home54:"Hot",home55:"Invest in Newly Issued Tokens and Tap into High Potential Returns",home56:"News",home57:"Why choose us?",home58:"Trusted by millions",home59:"Number of users",home60:"Partner unit",home61:"Minimum transaction fees",home62:"Partners",home63:"24h Vol",home64:"Unlock the New Era of Digital Wealth",home65:"Trade Safely, Invest Easily",home66:"Start Now",home67:"Smart Trading, Connected Future",home68:"Ultra-Fast Trading, Never Miss a Move",home69:"Digital Assets, Within Reach",jianguanzhengshu:"Giấy chứng nhận quản lý",falvzhengmingshu:"Giấy chứng nhận pháp lý",withdrawNote:"Thông báo rút tiền:<br><br>Thời gian xử lý rút tiền là 24 giờ<br><br>Sau khi gửi yêu cầu rút tiền, số tiền sẽ bị đóng băng vì giao dịch đang được xử lý và tạm thời được hệ thống bảo quản. Điều này không có nghĩa là tài sản của bạn bị mất hoặc có bất kỳ sự bất thường nào.<br><br>Yêu cầu rút token sẽ được ghi có trong vòng 12 giờ sau khi gửi. Nếu việc rút token không được ghi có sau thời gian dự kiến, vui lòng liên hệ dịch vụ khách hàng trực tuyến.<br><br>Rút tiền số lượng lớn phải được thực hiện bởi các thành viên VIP của chúng tôi. Vui lòng liên hệ dịch vụ khách hàng trực tuyến để biết thêm chi tiết."},yingshe:{miaoheyue:"Giao dịch quyền chọn",miaoheyuejiaoyi:"Giao dịch quyền chọn",heyuezhanghu:"Tài khoản giao dịch"},deltax:{company_bylaws:"Nội quy công ty",good_standing_certificate:"Giấy chứng nhận tình trạng tốt",about_title:"Về chúng tôi",about_text_1:"Chúng tôi là một trong những nền tảng giao dịch phát triển nhanh nhất châu Âu, với văn phòng tại Anh, châu Âu và Úc. Chúng tôi luôn đặt khách hàng làm trung tâm của mọi quyết định, thúc đẩy giao dịch của họ thông qua công nghệ trực quan, giáo dục chuyên sâu và hỗ trợ tận tâm.",about_text_2:"Sứ mệnh của chúng tôi là cung cấp cho các nhà giao dịch các công cụ và tài nguyên cần thiết để giao dịch tự tin và đưa ra quyết định tốt hơn. Sứ mệnh này đã mang lại cho chúng tôi nhiều giải thưởng từ các cơ quan thẩm quyền hàng đầu trong ngành.",stats_title:"Tổng quan phát triển",stat_global_label:"Vận hành toàn cầu",stat_global_desc:"Khi số lượng văn phòng toàn cầu của chúng tôi tiếp tục tăng, chúng tôi tự hào phục vụ khách hàng tại 183 quốc gia và khu vực",stat_global_link:"Tìm hiểu về giao dịch",stat_traders_label:"Nhà giao dịch",stat_traders_desc:"Kể từ khi ra mắt, cộng đồng nhà giao dịch toàn cầu của chúng tôi đã thực hiện khối lượng giao dịch vượt quá 53 tỷ đô la Mỹ",stat_traders_link:"Xem tin tức mới nhất",stat_support_label:"Nhân viên hỗ trợ",stat_support_desc:"Đội ngũ chăm sóc khách hàng thân thiện của chúng tôi luôn sẵn sàng 24/7 bằng 12 ngôn ngữ để hỗ trợ bạn mọi vấn đề liên quan đến tài khoản",stat_support_link:"Hỗ trợ",promise_title:"Cam kết của chúng tôi với khách hàng",promise_desc:"Giao dịch là một kỹ năng mà ít người thực sự thành thạo. Nhưng chúng tôi tin rằng, bằng cách kết hợp đúng cách công nghệ đổi mới, giáo dục sâu sắc và những hiểu biết độc đáo về hành vi giao dịch, bất kỳ ai cũng có thể phát triển chuyên môn giao dịch trên thị trường. Dù bạn là nhà giao dịch dày dạn hay mới bắt đầu, chúng tôi cung cấp các công cụ bạn cần để nâng cao kiến thức và kỹ năng.",promise_customer_name:"Khách hàng là trên hết",promise_customer_text:"Được xây dựng bởi các nhà giao dịch, chúng tôi áp dụng nghiên cứu chuyên sâu, khoa học dữ liệu và những hiểu biết độc đáo để phát triển các sản phẩm truyền cảm hứng cho khách hàng nâng cao",promise_innovation_name:"Không ngừng tiến bước",promise_innovation_text:"Chúng tôi cam kết liên tục tối ưu hóa nền tảng của mình để mang đến trải nghiệm người dùng mượt mà, cho phép giao dịch tự tin và đưa ra quyết định tốt hơn thông qua các công cụ đổi mới, lấy công nghệ làm trọng tâm",promise_transparency_name:"Luôn minh bạch",promise_transparency_text:"Chúng tôi nỗ lực phá vỡ rào cản giao dịch bằng cách cung cấp một trong những mức giá cạnh tranh nhất trong ngành, cùng với các tài nguyên giáo dục dễ sử dụng và phong phú",promise_expertise_name:"Chuyên môn là thế mạnh",promise_expertise_text:"Đội ngũ quốc tế của chúng tôi có hàng chục năm kinh nghiệm về công nghệ và chuyên môn giao dịch, tạo nền tảng cho một nền tảng thân thiện, lấy công nghệ làm trọng tâm và trực quan",expertise_title:"Chuyên môn của chúng tôi",expertise_text_1:"Là một nhà môi giới đoạt giải thưởng, chúng tôi được khách hàng công nhận nhờ trải nghiệm người dùng trực quan, lấy công nghệ làm động lực, hỗ trợ khách hàng chất lượng cao và giá trị vượt trội. Công nghệ là cốt lõi trong mọi hoạt động của chúng tôi, cung cấp các tính năng thông minh như dữ liệu thị trường theo thời gian thực, công cụ biểu đồ nâng cao và ứng dụng di động đáp ứng hỗ trợ giao dịch trên di động. Mục tiêu của chúng tôi là cung cấp cho các nhà giao dịch bán lẻ khả năng tiếp cận liền mạch các công cụ tài chính toàn cầu.",expertise_text_2:"Chúng tôi luôn tìm kiếm những cách mới để giúp khách hàng giao dịch tự tin và đưa ra quyết định sáng suốt hơn, cung cấp công nghệ mới nhất, tài nguyên giáo dục chuyên sâu và giá cả cạnh tranh trong môi trường giao dịch không ngừng thay đổi.",expertise_stat_traders:"Nhà giao dịch",expertise_stat_service:"Chăm sóc khách hàng",expertise_stat_unit_second:"giây",expertise_stat_speed_label:"Tốc độ khớp lệnh trung bình",expertise_stat_indicators:"Chỉ báo kỹ thuật",expertise_footnote:"Dựa trên dữ liệu máy chủ nội bộ của chúng tôi từ năm 2022",awards_title:"Đánh giá của ngành",awards_desc_1:"Các sản phẩm trực quan, dịch vụ khách hàng tận tâm và đổi mới liên tục của chúng tôi đã nhiều lần được công nhận bởi các cơ quan thẩm quyền hàng đầu trong ngành.",awards_desc_2:"Năm 2023, Deloitte Technology Fast 50 đã xếp chúng tôi là một trong 50 công ty công nghệ phát triển nhanh nhất tại Trung Đông và Síp. Dưới đây là một số giải thưởng gần đây của chúng tôi:",products_title:"Sản phẩm và dịch vụ của chúng tôi",product_cfd_name:"Giao dịch CFD",product_cfd_desc:"Mua hoặc bán ngoại hối, chỉ số, cổ phiếu, hàng hóa và nhiều công cụ khác, không có ngày đáo hạn cố định và không chịu thuế đánh dấu đối với cổ phiếu Anh",product_platform_name:"Nền tảng thân thiện",product_platform_desc:"Chúng tôi ưu tiên sự thuận tiện cho khách hàng, cho phép giao dịch qua máy tính để bàn, điện thoại và API",product_demo_name:"Tài khoản giao dịch thử",product_demo_desc:"Các nhà giao dịch có thể trải nghiệm nền tảng của chúng tôi không rủi ro bằng vốn ảo, đồng thời tối ưu hóa chiến lược giao dịch",product_education_name:"Giáo dục",product_education_desc:"Cung cấp cái nhìn sâu sắc về các yếu tố cơ bản và kỹ thuật mới nhất thúc đẩy thị trường, giúp nhà giao dịch đưa ra quyết định sáng suốt",product_more:"Thêm",products_footnote:"Cách xử lý thuế phụ thuộc vào hoàn cảnh cá nhân và có thể thay đổi hoặc khác biệt tại các khu vực pháp lý bên ngoài Vương quốc Anh",global_title:"Văn phòng toàn cầu",award_source_good_money:"Good Money Guide",award_source_online_money:"Online Money Awards",award_source_forexbrokers:"ForexBrokers.com",award_source_investment_trends:"Investment Trends",award_source_advfn:"ADVFN",award_source_ft:"Financial Times Investors’ Chronicle",award_good_money_guide:"Ứng dụng giao dịch tốt nhất 2023",award_online_money:"Nhà cung cấp CFD tốt nhất 2023",award_forexbrokers:"Nhà môi giới phát triển nhanh nhất 2023",award_investment_satisfaction:"Sự hài lòng tổng thể của khách hàng 2022",award_investment_value:"Giải thưởng giá trị tốt nhất 2022",award_advfn:"Nhà môi giới phát triển nhanh nhất 2023",award_ft_investors:"Hỗ trợ nhà đầu tư mới 2022"},licai:{zhiyawakuang:"Lợi suất thông minh",zhiyawakuangjiaoyi:"Giao dịch lợi suất thông minh"}};export{n as default};
